{
  "templateCode": "otp-login",
  "tag": "auth",
  "channels": {
    "sms": {
      "enabled": true,
      "body": {
        "default": "Your code is {{otp}}. Do not share it."
      },
      "payloadBindings": {
        "otp": "$.otp"
      }
    },
    "email": {
      "enabled": true,
      "subject": {
        "default": "Your login code"
      },
      "body": {
        "default": "Hello {{name}},\n\nYour code is {{otp}}."
      },
      "payloadBindings": {
        "otp": "$.otp",
        "name": "$.user.firstName"
      }
    }
  }
}

{
  "templateCode": "welcome-email",
  "tag": "onboarding",
  "channels": {
    "email": {
      "enabled": true,
      "subject": {
        "default": "Welcome aboard, {{name}}"
      },
      "body": {
        "default": "Hello {{name}}, your account is ready. Sign in to get started."
      },
      "payloadBindings": {
        "name": "$.user.firstName"
      }
    }
  }
}
